-- CAT-R24/R25, ampliación4.5/6.2 y plan9.1. Sin tarifas, fuentes o límites productivos sembrados.
-- La financiación corporativa usa la misma capacidad operativa, sin una tarifa comercial ficticia.
ALTER TABLE b0_regla_trabajo_manual ADD COLUMN financiacion varchar(30) NOT NULL DEFAULT 'SOLICITANTE',
 ALTER COLUMN creditos_por_ronda DROP NOT NULL,
 DROP CONSTRAINT b0_regla_trabajo_manual_creditos_por_ronda_check,
 ADD CONSTRAINT ck_regla_manual_financiacion CHECK(
 (financiacion='SOLICITANTE' AND creditos_por_ronda IS NOT NULL AND creditos_por_ronda>0)
 OR(financiacion='MANTENIMIENTO_BROX' AND creditos_por_ronda IS NULL));
CREATE OR REPLACE FUNCTION conservar_regla_trabajo_manual_b0() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_OP IN('DELETE','TRUNCATE') THEN RAISE EXCEPTION 'La regla manual conserva su historia';END IF;
 IF ROW(NEW.id,NEW.version,NEW.unidad,NEW.creditos_por_ronda,NEW.cota_rondas,NEW.desde,NEW.hasta,NEW.decision,NEW.responsable,NEW.evidencia,NEW.huella,NEW.habilitada,NEW.financiacion)
 IS DISTINCT FROM ROW(OLD.id,OLD.version,OLD.unidad,OLD.creditos_por_ronda,OLD.cota_rondas,OLD.desde,OLD.hasta,OLD.decision,OLD.responsable,OLD.evidencia,OLD.huella,OLD.habilitada,OLD.financiacion)
 THEN RAISE EXCEPTION 'Modificar la regla requiere otra versión aprobada';END IF;RETURN NEW;END;$$;
CREATE OR REPLACE FUNCTION comprobar_operacion_manual_b0() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE r b0_regla_trabajo_manual%ROWTYPE;BEGIN
 IF NEW.modalidad='MANUAL_I0' THEN
  SELECT * INTO r FROM b0_regla_trabajo_manual WHERE id=NEW.regla_manual AND version=NEW.version_regla_manual FOR SHARE;
  IF NOT FOUND OR r.financiacion<>'SOLICITANTE' OR NOT r.habilitada OR NEW.admitida_en<r.desde OR NEW.admitida_en>=r.hasta
   OR NEW.aceptada_en<>NEW.admitida_en OR NEW.maximo_creditos<>precision_manual_b0(r.creditos_por_ronda*NEW.rondas_previstas)
  THEN RAISE EXCEPTION 'La admisión manual exige regla vigente del solicitante y máximo aceptado exacto';END IF;
 END IF;RETURN NEW;END;$$;

CREATE TABLE i0_politica_mercado (
 id uuid NOT NULL,version varchar(80) NOT NULL,configuracion jsonb NOT NULL CHECK(jsonb_typeof(configuracion)='object'),
 regla uuid NOT NULL,version_regla varchar(80) NOT NULL,
 decision uuid NOT NULL REFERENCES b0_decision_plataforma(id),responsable bigint NOT NULL REFERENCES cuenta_acceso(id_cuenta_acceso),
 evidencia text NOT NULL CHECK(length(btrim(evidencia))>0),huella varchar(64) NOT NULL CHECK(huella~'^[0-9a-f]{64}$'),
 desde timestamptz NOT NULL,hasta timestamptz NOT NULL,habilitada boolean NOT NULL DEFAULT false,
 registrada_en timestamptz NOT NULL DEFAULT clock_timestamp(),retirada_en timestamptz,decision_retiro uuid REFERENCES b0_decision_plataforma(id),motivo_retiro text,
 PRIMARY KEY(id,version),FOREIGN KEY(regla,version_regla) REFERENCES b0_regla_trabajo_manual(id,version),CHECK(hasta>desde),
 CHECK((retirada_en IS NULL AND decision_retiro IS NULL AND motivo_retiro IS NULL) OR(retirada_en IS NOT NULL AND decision_retiro IS NOT NULL AND motivo_retiro IS NOT NULL AND length(btrim(motivo_retiro))>0))
);
-- Solicitud privada o mantenimiento real de plataforma. Nunca una organización/cuenta ficticia.
CREATE TABLE i0_trabajo_mercado (
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,id_solicitud uuid NOT NULL,
 organizacion_id bigint REFERENCES organizacion(id_organizacion),id_persona bigint,id_rol bigint,id_propiedad bigint,
 cuenta_solicitante bigint REFERENCES cuenta_acceso(id_cuenta_acceso),
 politica uuid NOT NULL,version_politica varchar(80) NOT NULL,
 huella_solicitud varchar(64) NOT NULL CHECK(huella_solicitud~'^[0-9a-f]{64}$'),huella_recurso varchar(64) NOT NULL CHECK(huella_recurso~'^[0-9a-f]{64}$'),
 contexto_minimo jsonb NOT NULL CHECK(jsonb_typeof(contexto_minimo)='object'),plan jsonb NOT NULL CHECK(jsonb_typeof(plan)='object'),
 rondas_previstas numeric(38,12) NOT NULL CHECK(rondas_previstas>0 AND rondas_previstas=trunc(rondas_previstas)),
 maximo_aceptado numeric(38,12),aceptada_en timestamptz NOT NULL,
 estado varchar(20) NOT NULL DEFAULT 'PENDIENTE' CHECK(estado IN('PENDIENTE','ASIGNADA','ENTREGADA','OBSERVADA','RECHAZADA','REVISADA','PUBLICADA','INCIDENCIA','RETIRADA')),
 version bigint NOT NULL DEFAULT 0 CHECK(version>=0),operador bigint REFERENCES cuenta_acceso(id_cuenta_acceso),
 concesion_operador uuid REFERENCES b0_atribucion_plataforma(id),entrega jsonb,huella_entrega varchar(64),
 revision uuid,cuenta_revisora bigint REFERENCES cuenta_acceso(id_cuenta_acceso),concesion_revision uuid REFERENCES b0_atribucion_plataforma(id),
 rondas_acreditadas numeric(38,12) CHECK(rondas_acreditadas>=0 AND rondas_acreditadas=trunc(rondas_acreditadas) AND rondas_acreditadas<=rondas_previstas),
 liquidada_en timestamptz,rondas_liquidadas numeric(38,12),revision_liquidada uuid,
 creada_en timestamptz NOT NULL DEFAULT clock_timestamp(),
 UNIQUE NULLS NOT DISTINCT(organizacion_id,id_solicitud),
 FOREIGN KEY(politica,version_politica) REFERENCES i0_politica_mercado(id,version),
 FOREIGN KEY(organizacion_id,id_persona) REFERENCES persona(organizacion_id,id_persona),
 FOREIGN KEY(organizacion_id,id_rol) REFERENCES persona_rol(organizacion_id,id_persona_rol),
 FOREIGN KEY(organizacion_id,id_propiedad) REFERENCES propiedad(organizacion_id,id_propiedad),
 FOREIGN KEY(organizacion_id,id_solicitud) REFERENCES b0_operacion_ia(organizacion_id,id_operacion) DEFERRABLE INITIALLY DEFERRED,
 CHECK((organizacion_id IS NOT NULL AND num_nonnulls(id_persona,id_rol,maximo_aceptado)=3 AND maximo_aceptado>0 AND cuenta_solicitante IS NULL)
    OR(organizacion_id IS NULL AND num_nonnulls(id_persona,id_rol,id_propiedad,maximo_aceptado)=0 AND cuenta_solicitante IS NOT NULL)),
 CHECK((operador IS NULL)=(concesion_operador IS NULL)),
 CHECK(huella_entrega IS NULL OR huella_entrega~'^[0-9a-f]{64}$'),
 CHECK(estado NOT IN('REVISADA','PUBLICADA') OR (revision IS NOT NULL AND rondas_acreditadas IS NOT NULL)),CHECK((entrega IS NULL)=(huella_entrega IS NULL)),
 CHECK((revision IS NULL AND cuenta_revisora IS NULL AND concesion_revision IS NULL) OR num_nonnulls(revision,cuenta_revisora,concesion_revision)=3),
 CHECK((liquidada_en IS NULL AND rondas_liquidadas IS NULL AND revision_liquidada IS NULL)
    OR(liquidada_en IS NOT NULL AND rondas_liquidadas IS NOT NULL AND rondas_liquidadas>=0
       AND rondas_liquidadas=trunc(rondas_liquidadas) AND rondas_liquidadas<=rondas_previstas AND revision_liquidada IS NOT NULL))
);
CREATE INDEX ix_i0_cola ON i0_trabajo_mercado(estado,creada_en,id);
CREATE INDEX ix_i0_ambito ON i0_trabajo_mercado(organizacion_id,id_propiedad,id);
-- Historia y salida transaccional de este caso; no worker/API de investigación ni otro bus.
CREATE TABLE i0_evento_mercado (
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,trabajo bigint NOT NULL REFERENCES i0_trabajo_mercado(id),
 comando uuid NOT NULL,huella varchar(64) NOT NULL CHECK(huella~'^[0-9a-f]{64}$'),tipo varchar(40) NOT NULL,
 version_trabajo bigint NOT NULL CHECK(version_trabajo>=0),cuenta bigint REFERENCES cuenta_acceso(id_cuenta_acceso),
 organizacion_id bigint,id_rol bigint,concesion uuid REFERENCES b0_atribucion_plataforma(id),
 contenido jsonb NOT NULL CHECK(jsonb_typeof(contenido)='object'),registrada_en timestamptz NOT NULL DEFAULT clock_timestamp(),
 UNIQUE(trabajo,comando),UNIQUE(trabajo,version_trabajo),
 FOREIGN KEY(organizacion_id,id_rol) REFERENCES persona_rol(organizacion_id,id_persona_rol),
 CHECK((cuenta IS NOT NULL AND concesion IS NOT NULL AND organizacion_id IS NULL AND id_rol IS NULL) OR(cuenta IS NULL AND concesion IS NULL AND organizacion_id IS NOT NULL AND id_rol IS NOT NULL))
);
CREATE TABLE i0_referencia_aprobada (
 id uuid PRIMARY KEY,trabajo bigint NOT NULL REFERENCES i0_trabajo_mercado(id),version_trabajo bigint NOT NULL,
 politica uuid NOT NULL,version_politica varchar(80) NOT NULL,segmento varchar(64) NOT NULL,
 proyeccion jsonb NOT NULL CHECK(jsonb_typeof(proyeccion)='object'),huella varchar(64) NOT NULL CHECK(huella~'^[0-9a-f]{64}$'),
 revisor bigint NOT NULL REFERENCES cuenta_acceso(id_cuenta_acceso),concesion uuid NOT NULL REFERENCES b0_atribucion_plataforma(id),
 desde timestamptz NOT NULL,hasta timestamptz NOT NULL,publicada_en timestamptz NOT NULL DEFAULT clock_timestamp(),
 retirada_en timestamptz,retirada_por bigint REFERENCES cuenta_acceso(id_cuenta_acceso),concesion_retiro uuid REFERENCES b0_atribucion_plataforma(id),motivo_retiro text,
 CHECK(num_nonnulls(retirada_en,retirada_por,concesion_retiro,motivo_retiro) IN(0,4)),
 FOREIGN KEY(politica,version_politica) REFERENCES i0_politica_mercado(id,version),UNIQUE(trabajo,version_trabajo),CHECK(hasta>desde)
);
CREATE INDEX ix_i0_referencia_segmento ON i0_referencia_aprobada(segmento,publicada_en DESC,id);
CREATE FUNCTION conservar_mercado_i0() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 RAISE EXCEPTION 'La evidencia y decisiones I0 conservan sus versiones e historia';END;$$;
CREATE TRIGGER evento_i0_conservar BEFORE UPDATE OR DELETE ON i0_evento_mercado FOR EACH ROW EXECUTE FUNCTION conservar_mercado_i0();
CREATE FUNCTION conservar_referencia_i0() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'La referencia conserva historia';END IF;
 IF (to_jsonb(NEW)-ARRAY['retirada_en','retirada_por','concesion_retiro','motivo_retiro']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['retirada_en','retirada_por','concesion_retiro','motivo_retiro'])
 OR OLD.retirada_en IS NOT NULL OR NEW.retirada_en IS NULL OR length(btrim(NEW.motivo_retiro))=0
 THEN RAISE EXCEPTION 'Una referencia conserva su version; solo se anade un retiro acreditado';END IF;RETURN NEW;END;$$;
CREATE TRIGGER referencia_i0_conservar BEFORE UPDATE OR DELETE ON i0_referencia_aprobada FOR EACH ROW EXECUTE FUNCTION conservar_referencia_i0();
CREATE TRIGGER evento_i0_truncate BEFORE TRUNCATE ON i0_evento_mercado FOR EACH STATEMENT EXECUTE FUNCTION conservar_mercado_i0();
CREATE TRIGGER referencia_i0_truncate BEFORE TRUNCATE ON i0_referencia_aprobada FOR EACH STATEMENT EXECUTE FUNCTION conservar_mercado_i0();
CREATE FUNCTION conservar_trabajo_i0() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_OP IN('DELETE','TRUNCATE') THEN RAISE EXCEPTION 'La investigación conserva su historia';END IF;
 IF ROW(NEW.id,NEW.id_solicitud,NEW.organizacion_id,NEW.id_persona,NEW.id_rol,NEW.id_propiedad,NEW.cuenta_solicitante,NEW.politica,NEW.version_politica,NEW.huella_solicitud,NEW.huella_recurso,NEW.contexto_minimo,NEW.plan,NEW.rondas_previstas,NEW.maximo_aceptado,NEW.aceptada_en,NEW.creada_en)
 IS DISTINCT FROM ROW(OLD.id,OLD.id_solicitud,OLD.organizacion_id,OLD.id_persona,OLD.id_rol,OLD.id_propiedad,OLD.cuenta_solicitante,OLD.politica,OLD.version_politica,OLD.huella_solicitud,OLD.huella_recurso,OLD.contexto_minimo,OLD.plan,OLD.rondas_previstas,OLD.maximo_aceptado,OLD.aceptada_en,OLD.creada_en)
 OR NEW.version<>OLD.version+1 THEN RAISE EXCEPTION 'El trabajo I0 conserva identidad, plan aceptado y versión concurrente';END IF;
 IF OLD.liquidada_en IS NOT NULL AND ROW(NEW.liquidada_en,NEW.rondas_liquidadas,NEW.revision_liquidada)
 IS DISTINCT FROM ROW(OLD.liquidada_en,OLD.rondas_liquidadas,OLD.revision_liquidada)
 THEN RAISE EXCEPTION 'Las correcciones no cambian la liquidación acreditada';END IF;
 RETURN NEW;END;$$;
CREATE TRIGGER trabajo_i0_conservar BEFORE UPDATE OR DELETE ON i0_trabajo_mercado FOR EACH ROW EXECUTE FUNCTION conservar_trabajo_i0();
CREATE TRIGGER trabajo_i0_truncate BEFORE TRUNCATE ON i0_trabajo_mercado FOR EACH STATEMENT EXECUTE FUNCTION conservar_trabajo_i0();
CREATE FUNCTION conservar_politica_i0() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_OP IN('DELETE','TRUNCATE') THEN RAISE EXCEPTION 'La política de mercado conserva su versión';END IF;
 IF ROW(NEW.id,NEW.version,NEW.configuracion,NEW.regla,NEW.version_regla,NEW.decision,NEW.responsable,NEW.evidencia,NEW.huella,NEW.desde,NEW.hasta,NEW.habilitada,NEW.registrada_en)
 IS DISTINCT FROM ROW(OLD.id,OLD.version,OLD.configuracion,OLD.regla,OLD.version_regla,OLD.decision,OLD.responsable,OLD.evidencia,OLD.huella,OLD.desde,OLD.hasta,OLD.habilitada,OLD.registrada_en)
 OR OLD.retirada_en IS NOT NULL OR NEW.retirada_en IS NULL THEN RAISE EXCEPTION 'Sólo se añade un retiro acreditado, nunca se sobrescribe una política';END IF;
 RETURN NEW;END;$$;
CREATE TRIGGER politica_i0_conservar BEFORE UPDATE OR DELETE ON i0_politica_mercado FOR EACH ROW EXECUTE FUNCTION conservar_politica_i0();
CREATE TRIGGER politica_i0_truncate BEFORE TRUNCATE ON i0_politica_mercado FOR EACH STATEMENT EXECUTE FUNCTION conservar_politica_i0();
CREATE FUNCTION verificar_integridad_trabajo_i0() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE t i0_trabajo_mercado%ROWTYPE;p i0_politica_mercado%ROWTYPE;r b0_regla_trabajo_manual%ROWTYPE;o b0_operacion_ia%ROWTYPE;
BEGIN
 SELECT * INTO t FROM i0_trabajo_mercado WHERE id=NEW.id;
 SELECT * INTO p FROM i0_politica_mercado WHERE id=t.politica AND version=t.version_politica;
 SELECT * INTO r FROM b0_regla_trabajo_manual WHERE id=p.regla AND version=p.version_regla;
 IF (SELECT count(*) FROM i0_evento_mercado WHERE trabajo=t.id)<>t.version+1
 OR (SELECT max(version_trabajo) FROM i0_evento_mercado WHERE trabajo=t.id) IS DISTINCT FROM t.version
 THEN RAISE EXCEPTION 'La actuación de mercado exige historia/salida en la misma transacción';END IF;
 IF EXISTS(SELECT 1 FROM i0_evento_mercado e LEFT JOIN b0_atribucion_plataforma g ON g.id=e.concesion
   WHERE e.trabajo=t.id AND ((e.organizacion_id IS NOT NULL AND e.organizacion_id IS DISTINCT FROM t.organizacion_id)
      OR(e.cuenta IS NOT NULL AND e.cuenta IS DISTINCT FROM g.cuenta)))
 THEN RAISE EXCEPTION 'El actor de la historia conserva su propio ámbito y concesión';END IF;
 IF t.organizacion_id IS NOT NULL THEN
  SELECT * INTO o FROM b0_operacion_ia WHERE organizacion_id=t.organizacion_id AND id_operacion=t.id_solicitud;
  IF NOT FOUND OR o.modalidad<>'MANUAL_I0' OR r.financiacion<>'SOLICITANTE'
   OR ROW(o.id_persona,o.id_rol,o.regla_manual,o.version_regla_manual,o.maximo_creditos,o.recurso_tipo,o.recurso_id,o.huella_origen,o.finalidad,o.rondas_previstas)
   IS DISTINCT FROM ROW(t.id_persona,t.id_rol,p.regla,p.version_regla,t.maximo_aceptado,'INVESTIGACION_MERCADO'::varchar,t.id_solicitud::varchar,t.huella_recurso,'INVESTIGACION_PUNTUAL'::varchar,t.rondas_previstas)
  THEN RAISE EXCEPTION 'La investigación conserva solicitante, alcance, regla y reserva B0 propios';END IF;
 ELSE
  IF r.financiacion<>'MANTENIMIENTO_BROX' THEN RAISE EXCEPTION 'El mantenimiento no utiliza financiación del profesional';END IF;
 END IF;
 RETURN NULL;END;$$;
CREATE CONSTRAINT TRIGGER integridad_trabajo_i0 AFTER INSERT OR UPDATE ON i0_trabajo_mercado DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION verificar_integridad_trabajo_i0();
CREATE FUNCTION cota_corporativa_i0() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE p i0_politica_mercado%ROWTYPE;
BEGIN
 IF NEW.organizacion_id IS NOT NULL THEN RETURN NEW;END IF;
 SELECT * INTO p FROM i0_politica_mercado WHERE id=NEW.politica AND version=NEW.version_politica;
 IF TG_OP='INSERT' THEN
  UPDATE b0_regla_trabajo_manual SET reservadas=reservadas+NEW.rondas_previstas
   WHERE id=p.regla AND version=p.version_regla AND financiacion='MANTENIMIENTO_BROX'
    AND reservadas+realizadas+NEW.rondas_previstas<=cota_rondas;
  IF NOT FOUND THEN RAISE EXCEPTION 'No hay cota corporativa de investigación disponible';END IF;
 ELSIF OLD.liquidada_en IS NULL AND NEW.liquidada_en IS NOT NULL THEN
  UPDATE b0_regla_trabajo_manual SET reservadas=reservadas-NEW.rondas_previstas,realizadas=realizadas+NEW.rondas_liquidadas
   WHERE id=p.regla AND version=p.version_regla AND reservadas>=NEW.rondas_previstas;
  IF NOT FOUND THEN RAISE EXCEPTION 'La investigación corporativa no conserva su reserva';END IF;
 END IF;RETURN NEW;END;$$;
CREATE TRIGGER cota_corporativa_i0 AFTER INSERT OR UPDATE ON i0_trabajo_mercado FOR EACH ROW EXECUTE FUNCTION cota_corporativa_i0();
